import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
    Box,
    TextField,
    Button,
    Typography,
    Alert,
    CircularProgress,
    InputAdornment,
    IconButton,
    Paper
} from '@mui/material';
import EmailIcon from '@mui/icons-material/Email';
import VisibilityIcon from '@mui/icons-material/Visibility';
import VisibilityOffIcon from '@mui/icons-material/VisibilityOff';
import { utilisateurService } from '../services/utilisateurService';

const Login: React.FC = () => {
    const navigate = useNavigate();
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [showPassword, setShowPassword] = useState(false);
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        
        if (!email || !password) {
            setError('Veuillez remplir tous les champs');
            return;
        }
        
        setLoading(true);
        setError(null);
        
        try {
            const response = await utilisateurService.connexion(email, password);
            
            console.log('Réponse complète:', response.data);
            
            // Stocker les données correctement
            const utilisateurData = {
                id: response.data.utilisateurId,
                pseudo: response.data.pseudo,
                email: response.data.email,
                photo_profil: response.data.photo_profil || null
            };
            
            sessionStorage.setItem('userId', response.data.utilisateurId.toString());
            sessionStorage.setItem('utilisateur', JSON.stringify(utilisateurData));
            
            console.log('Données stockées - userId:', sessionStorage.getItem('userId'));
            console.log('Données stockées - utilisateur:', sessionStorage.getItem('utilisateur'));
            
            // Redirection
            window.location.href = '/profil';
        } catch (err: any) {
            console.error('Erreur de connexion:', err);
            setError(err.response?.data?.error || 'Email ou mot de passe incorrect');
            setLoading(false);
        }
    };

    return (
        <Box sx={{
            minHeight: '100vh',
            background: 'linear-gradient(180deg, #ffffff 1%, #cfcfcf 43%, #999999 100%)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            position: 'relative'
        }}>
            <Box sx={{ position: 'absolute', left: '28px', top: '0' }}>
                <img src="/icons/logo.png" alt="Booklovers logo" style={{ width: 'auto', height: 'auto' }} />
            </Box>
            
            <Box sx={{ position: 'absolute', left: '135px', top: '192px', width: '400px', height: '400px' }}>
                <img 
                    src="/icons/auth.png" 
                    alt="Illustration" 
                    style={{ width: '100%', height: '100%', objectFit: 'cover' }}
                />
            </Box>
            
            <Paper elevation={0} sx={{
                position: 'absolute',
                left: '715px',
                top: '203px',
                width: '379px',
                padding: '20px 0',
                background: 'transparent',
                boxShadow: 'none'
            }}>
                <Typography variant="h4" sx={{
                    fontFamily: 'Poppins, sans-serif',
                    fontWeight: 800,
                    fontSize: '32px',
                    background: 'linear-gradient(34deg, #000204 0%, #773399 100%)',
                    WebkitBackgroundClip: 'text',
                    WebkitTextFillColor: 'transparent',
                    textAlign: 'center',
                    mb: '30px'
                }}>
                    Login
                </Typography>
                
                {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
                
                <form onSubmit={handleSubmit}>
                    <Box sx={{ mb: '25px' }}>
                        <Typography sx={{ fontFamily: 'Poppins', fontSize: '14px', color: '#333', mb: '8px' }}>
                            Email
                        </Typography>
                        <TextField
                            fullWidth
                            type="email"
                            placeholder="Votre email"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            required
                            sx={{
                                '& .MuiInputBase-root': {
                                    height: '37px',
                                    backgroundColor: '#a9a9a9',
                                    borderRadius: '15px',
                                    '& fieldset': { border: 'none' }
                                },
                                '& .MuiInputBase-input': {
                                    padding: '0 15px',
                                    fontFamily: 'Poppins',
                                    fontSize: '14px',
                                    color: '#333'
                                }
                            }}
                        />
                    </Box>

                    <Box sx={{ mb: '25px' }}>
                        <Typography sx={{ fontFamily: 'Poppins', fontSize: '14px', color: '#333', mb: '8px' }}>
                            Mot de passe
                        </Typography>
                        <TextField
                            fullWidth
                            type={showPassword ? 'text' : 'password'}
                            placeholder="Votre mot de passe"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            required
                            sx={{
                                '& .MuiInputBase-root': {
                                    height: '37px',
                                    backgroundColor: '#a9a9a9',
                                    borderRadius: '15px',
                                    '& fieldset': { border: 'none' }
                                },
                                '& .MuiInputBase-input': {
                                    padding: '0 15px',
                                    fontFamily: 'Poppins',
                                    fontSize: '14px',
                                    color: '#333'
                                }
                            }}
                            slotProps={{
                                input: {
                                    endAdornment: (
                                        <InputAdornment position="end">
                                            <IconButton onClick={() => setShowPassword(!showPassword)} edge="end">
                                                {showPassword ? <VisibilityOffIcon /> : <VisibilityIcon />}
                                            </IconButton>
                                        </InputAdornment>
                                    )
                                }
                            }}
                        />
                    </Box>

                    <Button
                        type="submit"
                        fullWidth
                        disabled={loading}
                        sx={{
                            width: '238px',
                            height: '50px',
                            background: 'linear-gradient(0deg, #01111d 0%, #773399 100%)',
                            borderRadius: '45px',
                            fontFamily: 'Poppins',
                            fontWeight: 800,
                            fontSize: '20px',
                            color: 'white',
                            margin: '15px auto 25px auto',
                            display: 'block',
                            '&:hover': {
                                opacity: 0.9,
                                transform: 'translateY(-2px)'
                            }
                        }}
                    >
                        {loading ? <CircularProgress size={28} /> : 'CONNECTER'}
                    </Button>

                    <Box sx={{ display: 'flex', justifyContent: 'space-between', width: '100%' }}>
                        <Typography
                            component="a"
                            href="/inscription"
                            sx={{ color: '#333', textDecoration: 'none', '&:hover': { color: '#773399' } }}
                        >
                            Créer un compte
                        </Typography>
                        <Typography
                            component="a"
                            href="/mdpOublie"
                            sx={{ color: '#333', textDecoration: 'none', '&:hover': { color: '#773399' } }}
                        >
                            Mot de passe oublié
                        </Typography>
                    </Box>
                </form>
            </Paper>
        </Box>
    );
};

export default Login;
